import boto3


def stream_completion(payload, config=None):
    config = config or {}
    client = boto3.client("bedrock-runtime", region_name=config.get("region"))
    prompt = payload["text"]
    response = client.converse(
        modelId="amazon.nova-pro-v1:0",
        messages=[{"role": "user", "content": [{"text": prompt}]}],
        stream=True,
    )
    for event in response["output"]["message"]["content"]:
        if "text" in event:
            yield event["text"]
    return

import boto3


def get_bedrock_client(region=None):
    return boto3.client("bedrock-runtime", region_name=region)


def get_model_id(model_family):
    model_map = {
        "nova-pro": "amazon.nova-pro-v1:0",
    }
    return model_map.get(model_family)

def normalize_payload(payload):
    return {
        "text": payload.get("text", ""),
    }


def normalize_response(response):
    return {
        "text": response.get("text", ""),
    }

import re


def check_safety(text):
    unsafe_patterns = [
        r"hate speech",
        r"violence",
        r"discrimination",
    ]
    for pattern in unsafe_patterns:
        if re.search(pattern, text, re.IGNORECASE):
            return False
    return True
